WITH flattened AS (SELECT id, service, host, latency_ms, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS key, attr_value) SELECT CASE WHEN latency_ms >= 2225 THEN 'HIGH' ELSE 'LOW' END AS latency_ms_tier, BIT_AND(latency_ms) AS latency_ms_bit_and, SIZE(COLLECT_SET(host)) AS num_hosts, COUNT_IF(service = 'auth') AS auth_events, SUM(CASE WHEN service = 'checkout' THEN latency_ms ELSE 0 END) AS checkout_latency_ms, STDDEV_SAMP(latency_ms) AS latency_ms_stddev, ROUND(AVG(latency_ms), 2) AS avg_latency_ms FROM flattened GROUP BY 1 ORDER BY checkout_latency_ms DESC;
